// Filter overdue and high-priority pending follow-ups requiring staff attention
const items = $input.all();
const now = new Date();
const overdueOrUrgent = [];

for (const item of items) {
  const tasks = item.json.data || [];
  for (const task of tasks) {
    const isOverdue = task.due_at && new Date(task.due_at) < now;
    const isUrgent = task.priority === 'urgent' || task.priority === 'high';

    // Flag if overdue, urgent, or unassigned older than 48 hours
    const ageHours = (now.getTime() - new Date(task.created_at).getTime()) / (1000 * 60 * 60);
    const isStaleUnassigned = !task.assigned_to && ageHours > 48;

    if (isOverdue || isUrgent || isStaleUnassigned) {
      overdueOrUrgent.push({
        id: task.id,
        client_id: task.client_id,
        priority: task.priority,
        reason: task.reason,
        is_overdue: isOverdue,
        is_urgent: isUrgent,
        is_stale: isStaleUnassigned
      });
    }
  }
}

return [{
  json: {
    total_pending_flagged: overdueOrUrgent.length,
    tasks: overdueOrUrgent,
    generated_at: now.toISOString()
  }
}];

// Format coordinator summary digest
const data = $input.first().json;
const summaryMessage = `Care Coordinator Alert: ${data.total_pending_flagged} pending follow-up task(s) require attention (overdue or high priority).`;

return [{
  json: {
    event: 'FOLLOWUP_COORDINATOR_DIGEST',
    summary: summaryMessage,
    task_count: data.total_pending_flagged,
    tasks: data.tasks,
    dispatched_at: new Date().toISOString()
  }
}];
